import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the CUDA kernel for matrix multiplication with loop unrolling
cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

#define UNROLL_FACTOR 4

__global__ void matmul_kernel(const float* A, const float* B, float* C, int N) {
    // Block size is 16x16
    const int BLOCK_SIZE = 16;

    // Shared memory for tiles of A and B
    __shared__ float As[BLOCK_SIZE][BLOCK_SIZE];
    __shared__ float Bs[BLOCK_SIZE][BLOCK_SIZE];

    // Thread indices
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    // Block indices
    int bx = blockIdx.x;
    int by = blockIdx.y;

    // Compute row and column of C element to compute
    int row = by * BLOCK_SIZE + ty;
    int col = bx * BLOCK_SIZE + tx;

    float sum = 0.0f;

    // Loop over tiles with unrolling
    int numTiles = (N + BLOCK_SIZE - 1) / BLOCK_SIZE;

    for (int t = 0; t < numTiles; t += UNROLL_FACTOR) {
        // Preload multiple tiles
        for (int i = 0; i < UNROLL_FACTOR; i++) {
            int t_idx = t + i;
            if (t_idx < numTiles) {
                // Compute indices for loading tiles
                int a_col = t_idx * BLOCK_SIZE + tx;
                int b_row = t_idx * BLOCK_SIZE + ty;

                // Load tile of A
                if (row < N && a_col < N) {
                    As[ty][tx] = A[row * N + a_col];
                } else {
                    As[ty][tx] = 0.0f;
                }

                // Load tile of B
                if (b_row < N && col < N) {
                    Bs[ty][tx] = B[b_row * N + col];
                } else {
                    Bs[ty][tx] = 0.0f;
                }

                __syncthreads();

                // Compute partial sum for this tile
                for (int k = 0; k < BLOCK_SIZE; k++) {
                    sum += As[ty][k] * Bs[k][tx];
                }

                __syncthreads();
            }
        }
    }

    // Store result
    if (row < N && col < N) {
        C[row * N + col] = sum;
    }
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    int N = A.size(0);
    auto options = torch::TensorOptions().dtype(A.dtype()).device(A.device());
    auto C = torch::empty({N, N}, options);

    dim3 block_size(16, 16);
    dim3 grid_size((N + block_size.x - 1) / block_size.x, (N + block_size.y - 1) / block_size.y);

    matmul_kernel<<<grid_size, block_size>>>(A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), N);

    return C;
}
"""

